from collections import deque

def num_buses_to_destination(routes, source, target):
    if source == target:
        return 0
    stop_to_buses = {}
    for bus_idx, route in enumerate(routes):
        for stop in route:
            stop_to_buses.setdefault(stop, []).append(bus_idx)
    visited_buses = set()
    visited_stops = {source}
    queue = deque([source])
    buses = 0
    while queue:
        buses += 1                                              # one MORE bus ride
        for _ in range(len(queue)):
            stop = queue.popleft()
            for bus_idx in stop_to_buses.get(stop, []):
                if bus_idx in visited_buses:
                    continue
                visited_buses.add(bus_idx)
                for next_stop in routes[bus_idx]:                    # reach ALL stops on this bus's route
                    if next_stop == target:
                        return buses
                    if next_stop not in visited_stops:
                        visited_stops.add(next_stop)
                        queue.append(next_stop)
    return -1

