import java.util.*;

public class Main {
    static int numBusesToDestination(int[][] routes, int source, int target) {
        if (source == target) return 0;
        Map<Integer, List<Integer>> stopToBuses = new HashMap<>();
        for (int busIdx = 0; busIdx < routes.length; busIdx++) {
            for (int stop : routes[busIdx]) {
                stopToBuses.computeIfAbsent(stop, k -> new ArrayList<>()).add(busIdx);
            }
        }
        Set<Integer> visitedBuses = new HashSet<>();
        Set<Integer> visitedStops = new HashSet<>();
        visitedStops.add(source);
        Queue<Integer> queue = new LinkedList<>();
        queue.add(source);
        int buses = 0;
        while (!queue.isEmpty()) {
            buses++;                                                    // one MORE bus ride
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int stop = queue.poll();
                for (int busIdx : stopToBuses.getOrDefault(stop, new ArrayList<>())) {
                    if (visitedBuses.contains(busIdx)) continue;
                    visitedBuses.add(busIdx);
                    for (int nextStop : routes[busIdx]) {                    // reach ALL stops on this bus's route
                        if (nextStop == target) return buses;
                        if (!visitedStops.contains(nextStop)) {
                            visitedStops.add(nextStop);
                            queue.add(nextStop);
                        }
                    }
                }
            }
        }
        return -1;
    }
}

