int numBusesToDestination(vector<vector<int>>& routes, int source, int target) {
    if (source == target) return 0;
    unordered_map<int, vector<int>> stopToBuses;
    for (int busIdx = 0; busIdx < (int)routes.size(); busIdx++) {
        for (int stop : routes[busIdx]) stopToBuses[stop].push_back(busIdx);
    }
    unordered_set<int> visitedBuses, visitedStops;
    visitedStops.insert(source);
    queue<int> q;
    q.push(source);
    int buses = 0;
    while (!q.empty()) {
        buses++;                                                          // one MORE bus ride
        int size = q.size();
        for (int i = 0; i < size; i++) {
            int stop = q.front(); q.pop();
            for (int busIdx : stopToBuses[stop]) {
                if (visitedBuses.count(busIdx)) continue;
                visitedBuses.insert(busIdx);
                for (int nextStop : routes[busIdx]) {                           // reach ALL stops on this bus's route
                    if (nextStop == target) return buses;
                    if (!visitedStops.count(nextStop)) {
                        visitedStops.insert(nextStop);
                        q.push(nextStop);
                    }
                }
            }
        }
    }
    return -1;
}
